<?php
declare(strict_types=1);
ini_set('display_errors','0');
function private_dir():string{$p=getenv('REFUGIO_PRIVATE_DIR')?:dirname(__DIR__).'/private';if(!is_dir($p))mkdir($p,0700,true);return $p;}
function txt(mixed $s,int $max=1000):string{return is_string($s)?mb_substr(trim($s),0,$max):'';}
function out(int $code,array $d):never{http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function read_json(string $p,array $default=[]):array{$d=json_decode(@file_get_contents($p)?:'',true);return is_array($d)?$d:$default;}
function atomic_json(string $p,array $d):void{$tmp=$p.'.'.bin2hex(random_bytes(6)).'.tmp';file_put_contents($tmp,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);chmod($tmp,0600);rename($tmp,$p);}
function locked(string $name,callable $fn):mixed{$f=fopen(private_dir().'/'.$name.'.lock','c');if(!$f||!flock($f,LOCK_EX))throw new RuntimeException('Não foi possível obter acesso exclusivo.');try{return $fn();}finally{flock($f,LOCK_UN);fclose($f);}}
function settings():array{return read_json(private_dir().'/site-settings.json',read_json(__DIR__.'/defaults.json'));}
function body():array{$raw=file_get_contents('php://input',false,null,0,150001);if(strlen($raw)>150000)out(413,['erro'=>'Os dados são muito grandes.']);try{$d=json_decode($raw,true,64,JSON_THROW_ON_ERROR);}catch(Throwable){out(400,['erro'=>'Dados inválidos.']);}if(!is_array($d))out(400,['erro'=>'Dados inválidos.']);return $d;}
function rate(string $scope,int $max,int $window=600):void{$key=hash('sha256',($_SERVER['REMOTE_ADDR']??'test').$scope);$ok=locked('rate-'.$key,function()use($key,$max,$window){$p=private_dir().'/rate-'.$key.'.json';$d=read_json($p);if(time()-($d['at']??0)>$window)$d=['at'=>time(),'count'=>0];$d['count']=($d['count']??0)+1;atomic_json($p,$d);return $d['count']<=$max;});if(!$ok){header('Retry-After: '.$window);out(429,['erro'=>'Muitas tentativas. Aguarde alguns minutos.']);}}
function same_origin():bool{$origin=$_SERVER['HTTP_ORIGIN']??'';$expected='https://'.($_SERVER['HTTP_HOST']??'');if(getenv('REFUGIO_TEST_MODE')==='1')$expected='http://'.($_SERVER['HTTP_HOST']??'');return $origin===$expected;}
function public_origin():void{$origin=$_SERVER['HTTP_ORIGIN']??'';$own=(getenv('REFUGIO_TEST_MODE')==='1'?'http://':'https://').($_SERVER['HTTP_HOST']??'');$allowed=['https://comandante22.github.io',$own];header('Vary: Origin');if(!in_array($origin,$allowed,true))out(403,['erro'=>'Origem não permitida.']);header('Access-Control-Allow-Origin: '.$origin);if($_SERVER['REQUEST_METHOD']==='OPTIONS'){header('Access-Control-Allow-Methods: POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type');header('Access-Control-Max-Age: 600');http_response_code(204);exit;}if($_SERVER['REQUEST_METHOD']!=='POST')out(405,['erro'=>'Use POST.']);if(!str_contains($_SERVER['CONTENT_TYPE']??'','application/json'))out(415,['erro'=>'Envie JSON.']);}
function https_or_local(mixed $s):string{$s=txt($s,2000);if($s==='')return '';if(preg_match('~^(assets/|uploads/)[a-zA-Z0-9_./-]+$~',$s)&&!str_contains($s,'..'))return $s;$u=parse_url($s);if(($u['scheme']??'')==='https'&&!isset($u['user'])&&!isset($u['pass'])&&filter_var($s,FILTER_VALIDATE_URL))return $s;throw new InvalidArgumentException('Use um endereço HTTPS válido ou um arquivo do site.');}
function money(mixed $x):float{if(!is_numeric($x)||!is_finite((float)$x)||(float)$x<0||(float)$x>1000000)throw new InvalidArgumentException('Informe um preço entre 0 e 1.000.000.');return round((float)$x,2);}
function sanitize_settings(array $d):array{
 $defaults=read_json(__DIR__.'/defaults.json');$r=$defaults;$r['revision']=max(1,(int)($d['revision']??1));
 foreach(['name','tagline','heroTitle','heroText','contactName','contactEmail','seoTitle','seoDescription'] as $k)$r['brand'][$k]=txt($d['brand'][$k]??'',in_array($k,['heroText','seoDescription'])?600:200);
 $r['brand']['whatsapp']=preg_replace('/\D/','',txt($d['brand']['whatsapp']??'',30));if(!preg_match('/^\d{10,15}$/',$r['brand']['whatsapp']))throw new InvalidArgumentException('WhatsApp deve conter país, DDD e número.');
 $r['brand']['logo']=https_or_local($d['brand']['logo']??'');
 foreach(['siteCash','installmentValue']as$k)$r['pricing'][$k]=money($d['pricing'][$k]??null);$r['pricing']['installments']=max(1,min(24,(int)($d['pricing']['installments']??12)));foreach(['guarantee','delivery']as$k)$r['pricing'][$k]=txt($d['pricing'][$k]??'',1500);
 foreach($r['plans']as$i=>&$p){$v=$d['plans'][$i]??null;if(!is_array($v)||($v['id']??'')!==$p['id'])throw new InvalidArgumentException('A estrutura dos planos não pode ser alterada.');foreach(['name','description']as$k)$p[$k]=txt($v[$k]??'',300);$p['price']=money($v['price']??null);$p['enabled']=(bool)($v['enabled']??true);$p['features']=array_values(array_filter(array_map(fn($f)=>txt($f,200),array_slice(is_array($v['features']??null)?$v['features']:[],0,12))));}unset($p);
 $r['ads']=[];foreach(array_slice(is_array($d['ads']??null)?$d['ads']:[],0,10)as$i=>$a){$link=txt($a['link']??'',1000);if(!preg_match('/^[a-z0-9-]+\.html(?:\?[a-zA-Z0-9_=&%.-]*)?$/',$link))$link=https_or_local($link);$r['ads'][]=['id'=>'anuncio-'.$i,'title'=>txt($a['title']??'',200),'text'=>txt($a['text']??'',1000),'button'=>txt($a['button']??'',80),'link'=>$link,'image'=>https_or_local($a['image']??''),'enabled'=>(bool)($a['enabled']??false)];}
 $r['ai']['name']=txt($d['ai']['name']??'Bia',60);$r['ai']['tone']=txt($d['ai']['tone']??'',500);$r['ai']['instructions']=txt($d['ai']['instructions']??'',16000);$r['ai']['faq']=[];foreach(array_slice(is_array($d['ai']['faq']??null)?$d['ai']['faq']:[],0,30)as$f)$r['ai']['faq'][]=['question'=>txt($f['question']??'',300),'answer'=>txt($f['answer']??'',1500)];
 foreach($r['models']as$i=>&$m){$v=$d['models'][$i]??[];if(($v['id']??'')!==$m['id'])throw new InvalidArgumentException('Modelo inválido.');foreach(['name','tagline','description']as$k)$m[$k]=txt($v[$k]??$m[$k],500);$m['enabled']=(bool)($v['enabled']??true);$m['image']=https_or_local($v['image']??$m['image']);$m['price']=isset($v['price'])&&$v['price']!==''?money($v['price']):null;$m['order']=max(0,min(99,(int)($v['order']??$i)));foreach(['background','ink','accent']as$k){$c=txt($v[$k]??$m[$k],20);if(!preg_match('/^#[0-9a-f]{6}$/i',$c))throw new InvalidArgumentException('Cor inválida.');$m[$k]=$c;}}unset($m);
 return $r;
}
function sales_catalog(array $s):string{$p=$s['pricing'];$text='OFERTAS VIGENTES DO REFÚGIO (fonte única de preços): Site R$ '.number_format($p['siteCash'],2,',','.').' no Pix; cartão '.$p['installments'].'x de R$ '.number_format($p['installmentValue'],2,',','.').' (total R$ '.number_format($p['installments']*$p['installmentValue'],2,',','.').'). ';foreach($s['plans']as$plan)if($plan['enabled'])$text.=$plan['name'].': R$ '.number_format($plan['price'],2,',','.').'/mês. '.implode('; ',$plan['features']).'. ';$text.='PMS somente cartão recorrente; sem comissão do Refúgio; taxas externas dependem do provedor. '.$p['guarantee'].' '.$p['delivery'].'\nModelos disponíveis: ';foreach($s['models']as$m)if($m['enabled'])$text.=$m['name'].' ('.$m['id'].'): '.$m['tagline'].'; ';return $text;}
